// SPDX-License-Identifier: UNLICENSED
pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {Proxy} from "../src/Proxy.sol";

contract InvMutTest is Test {
    Proxy c;
    function setUp() public { c = new Proxy(); }
    function testFuzz_property(bytes memory data) public {
        vm.assume(data.length > 0);
        Pick payload = new Pick();
        bool ok = true;
        try c.forward(address(payload), data) { ok = true; } catch { ok = false; }
        assertTrue(!ok);
    }
}

contract Pick {
    fallback() external payable {
        if (msg.data.length > 0) revert();
    }
}
